// Scripts for rust/host/parity.mjs, by rewrite family of src/rewriteJS.ts:
// each is rewritten by both backends and the outputs compared. A string is a
// classic script; `m(...)` a module. Shapes a real corpus rarely has (the
// optional-chain forms, the postMessage call shapes, `var location`) are
// here so every family is compared, not only the common ones.
const m = (code) => ({ code, module: true });
// a shape the two backends are known to answer differently, and why: the
// harness lists these apart and does not fail on them
const d = (code, why) => ({ code, diverges: why });

