/** every case as {name, code, module} */
export function cases() {
	const out = [];
	for (const [family, list] of Object.entries(families))
		list.forEach((entry, index) => {
			const {
				code,
				module = false,
				diverges,
			} = typeof entry === 'string' ? { code: entry } : entry;
			out.push({
				name: `${family}#${index}`,
				family,
				text: code,
				module,
				diverges,
			});
		});
	return out;
}
